func main() {
	ctx := context.Background()
	client, err := pubsub.NewClient(ctx, "my-project")
	if err != nil {
		log.Fatal(err)
	}
	defer client.Close()

	result := client.Topic("my-topic").Publish(ctx, &pubsub.Message{Data: []byte("hello")})
